# Auto-added for portable DongLanpec venv: lock PyQt5 to its own Qt DLLs.
import os
import sys

def _donglan_fix_qt_dlls():
    try:
        import PyQt5
        root = os.path.dirname(PyQt5.__file__)
    except Exception:
        return
    qt5 = os.path.join(root, "Qt5")
    qt_bin = os.path.join(qt5, "bin")
    qt_plugins = os.path.join(qt5, "plugins")
    qt_platforms = os.path.join(qt_plugins, "platforms")
    if os.path.isdir(qt_plugins):
        os.environ["QT_PLUGIN_PATH"] = qt_plugins
    if os.path.isdir(qt_platforms):
        os.environ["QT_QPA_PLATFORM_PLUGIN_PATH"] = qt_platforms
    # Prefer our Qt bin on PATH
    if os.path.isdir(qt_bin):
        os.environ["PATH"] = qt_bin + os.pathsep + os.environ.get("PATH", "")
        if hasattr(os, "add_dll_directory"):
            try:
                os.add_dll_directory(qt_bin)
            except Exception:
                pass
    # Drop known polluters from PATH (AutoCAD / Conda Qt)
    cleaned = []
    for p in os.environ.get("PATH", "").split(os.pathsep):
        low = p.lower()
        if ("autocad" in low) or ("anaconda" in low) or (("conda" in low) and ("qt" in low)):
            continue
        cleaned.append(p)
    # keep qt_bin first
    if os.path.isdir(qt_bin):
        cleaned = [qt_bin] + [x for x in cleaned if x != qt_bin]
    os.environ["PATH"] = os.pathsep.join(cleaned)

_donglan_fix_qt_dlls()
